import{Z as s,e,f as a,a0 as o}from"./chunks/framework.DmpHOl9T.js";const d=JSON.parse('{"title":"Form Statuses","description":"","frontmatter":{},"headers":[],"relativePath":"forms/form-statuses.md","filePath":"forms/form-statuses.md","lastUpdated":1782349593000}'),r={name:"forms/form-statuses.md"};function n(i,t,l,m,u,h){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="form-statuses" tabindex="-1">Form Statuses <a class="header-anchor" href="#form-statuses" aria-label="Permalink to &quot;Form Statuses&quot;">​</a></h1><p>Form statuses label a form’s lifecycle state in the control panel — for example <strong>Active</strong>, <strong>Draft</strong>, or <strong>Archived</strong>.</p><p>They are separate from <a href="/submissions/submission-statuses">Submission Statuses</a>, which track workflow labels on individual submissions after they are saved.</p><h2 id="managing-form-statuses" tabindex="-1">Managing Form Statuses <a class="header-anchor" href="#managing-form-statuses" aria-label="Permalink to &quot;Managing Form Statuses&quot;">​</a></h2><p>Form statuses are managed under <strong>Formie → Settings → Form Statuses</strong>.</p><p>Each status has:</p><ul><li>a name</li><li>a handle</li><li>a colour</li><li>an optional description</li></ul><p>One status can be marked as the default for new forms.</p><p>Statuses are stored in project config, so they travel with the project like other shared Formie settings.</p><h2 id="assigning-a-form-status" tabindex="-1">Assigning a Form Status <a class="header-anchor" href="#assigning-a-form-status" aria-label="Permalink to &quot;Assigning a Form Status&quot;">​</a></h2><p>When editing a form, choose <strong>Form Status</strong> in the form settings sidebar. This appears before the form group field.</p><p>You can also:</p><ul><li>filter the forms index using the <strong>Status</strong> menu in the toolbar (pick a group in the sidebar first, then filter by status)</li><li>show <strong>Form Status</strong> as a table column in the index customise menu</li><li>bulk-update forms with the <strong>Set form status</strong> element action</li><li>use form status in element export conditions</li></ul><p>Form statuses are organisational labels only. They do not change whether a form accepts submissions or how it renders on the front-end.</p>',14)])])}const p=s(r,[["render",n]]);export{d as __pageData,p as default};
